-- MP-0051: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'MP-0051: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0051: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohamad-alamin','siti-aminah-aching','matbali-musah') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0051: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kimanis','beaufort','sipitang') and slug not in ('mohamad-alamin','siti-aminah-aching','matbali-musah')) then raise exception 'MP-0051: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0051:%' and (m.source_type <> 'editorial' or e.slug not in ('mohamad-alamin','siti-aminah-aching','matbali-musah') or m.import_key not like 'MP-0051:' || e.slug || ':%')) then raise exception 'MP-0051: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohamad-alamin','Mohamad Alamin','government','Deputy Minister of Entrepreneur Development and Cooperatives','Kimanis','Sabah','Mohamad Alamin represents Kimanis, Sabah, in the Dewan Rakyat. Current role: Deputy Minister of Entrepreneur Development and Cooperatives. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4215','/portraits/mohamad-alamin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P176.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4215"}, {"label": "UMNO · current supreme council member, 5 November 2026", "url": "https://umno-online.my/2026/11/05/lebih-200-inisiatif-kerajaan-melaka-jadi-ukuran-prestasi-mohamad-alamin/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'siti-aminah-aching','Siti Aminah Aching','government','Member of the Dewan Rakyat','Beaufort','Sabah','Siti Aminah Aching represents Beaufort, Sabah, in the Dewan Rakyat. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4216','/portraits/siti-aminah-aching.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P177.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4216"}, {"label": "UMNO · current supreme council member, 8 November 2026", "url": "https://umno-online.my/2026/11/08/siti-aminah-santuni-jentera-menerusi-jom-mengambuyat/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'matbali-musah','Matbali Musah','government','Member of the Dewan Rakyat','Sipitang','Sabah','Matbali Musah represents Sipitang, Sabah, in the Dewan Rakyat. Parliament records affiliation with Gabungan Rakyat Sabah (GRS).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4217','/portraits/matbali-musah.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/sipitang%20portal.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4217"}, {"label": "GRS MPs · current representation, 9 January 2026", "url": "https://gagasanrakyat.my/empat-kerusi-parlimen-sabah-kekal-mahkamah-persekutuan-tolak-permohonan-bersatu/"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mohamad-alamin','siti-aminah-aching','matbali-musah') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0051: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0051:mohamad-alamin:national-entrepreneur-repository-study','Study the feasibility of a National Entrepreneur Repository','Economy',null,null,null,'2026-02-05','https://umno-online.my/2026/02/05/kuskop-perkukuh-penyelarasan-program-keusahawanan-elak-pertindihan-mohamad-alamin/',null,null,'Mohamad Alamin announced a 2026 feasibility study to examine integrating KUSKOP agency databases into a central entrepreneur-data hub.','The undertaking is specific to the feasibility study. A completed study, approved nationwide repository, launch date and numerical progress were not established. Earlier SMEIPA programme totals do not measure this new study.','2026-11-10','editorial',false from public.entities e where e.slug='mohamad-alamin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0051:mohamad-alamin:thaifex-trade-mission-2026','Lead the Malaysian THAIFEX trade mission in Bangkok','Economy','achieved',null,null,null,null,'2026-05-29','https://www.kln.gov.my/web/tha_bangkok/post/yb-datuk-mohamad-alamin-deputy-minister-of-entrepreneur-and-cooperatives-development-kuskop-working-visit-to-bangkok-thailand','The Malaysian embassy reported Alamin’s 25–29 May mission, including Malaysian pavilions, bilateral discussions and business-engagement sessions. The exhibition included 158 Malaysian exhibitors.','Achieved covers the documented mission, not signed sales, realised exports or later investment. Multiple ministries and business groups contributed to the delegation.','2026-11-10','editorial',false from public.entities e where e.slug='mohamad-alamin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0051:matbali-musah:sindumin-christmas-support-2024','Provide Christmas contributions to 45 Sindumin churches','Community Development','achieved',null,null,null,null,'2024-12-09','https://gagasanrakyat.my/matbali-yusof-sampaikan-sumbangan-kepada-45-gereja/','A party report records Matbali and Sindumin representative Yusof Yacob jointly presenting support to ten larger and 35 smaller churches.','This is a December 2024 report of an earlier handover, not a new November 2026 allocation. Achieved covers that joint contribution round only; recipient spending and future rounds were not verified.','2026-11-10','editorial',false from public.entities e where e.slug='matbali-musah' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

